[CmdletBinding(SupportsShouldProcess=$true)]
param(
    [ValidateSet('Check','DryRun','Apply','Verify','VerifyReboot','Rollback')]
    [string]$Action='Check',
    [string]$StatePath="$env:ProgramData\Lacksan\EXP-015\state.json",
    [string]$LogPath="$env:ProgramData\Lacksan\EXP-015\events.jsonl"
)
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
$RunPaths=@('HKCU:\Software\Microsoft\Windows\CurrentVersion\Run','HKCU:\Software\Microsoft\Windows\CurrentVersion\RunOnce')
$Protected='(?i)(edgeupdate|microsoftedgeupdate|webview2|msedgewebview2|omnissa|horizon|tailscale|remote\s*desktop|windows\s*app|security|defender)'
function Write-Event([string]$Event,[string]$Result,[hashtable]$Data=@{}) { $d=Split-Path -Parent $LogPath; if($d -and -not(Test-Path $d)){New-Item -ItemType Directory -Path $d -Force|Out-Null}; [ordered]@{timestampUtc=(Get-Date).ToUniversalTime().ToString('o');experiment='EXP-015';action=$Action;event=$Event;result=$Result;data=$Data}|ConvertTo-Json -Compress -Depth 8|Add-Content -LiteralPath $LogPath -Encoding UTF8 }
function Get-Support { $os=Get-CimInstance Win32_OperatingSystem; $cs=Get-CimInstance Win32_ComputerSystem; $edge=@("$env:ProgramFiles(x86)\Microsoft\Edge\Application\msedge.exe","$env:ProgramFiles\Microsoft\Edge\Application\msedge.exe")|Where-Object{Test-Path $_}|Select-Object -First 1; [pscustomobject]@{Supported=($os.Caption-match'Windows 11'-and$cs.Manufacturer-match'(?i)HP|Hewlett'-and[bool]$edge);Windows=$os.Caption;Build=$os.BuildNumber;Manufacturer=$cs.Manufacturer;Model=$cs.Model;EdgePath=$edge} }
function Test-Candidate([string]$Name,[string]$Command) { if([string]::IsNullOrWhiteSpace($Name)-or[string]::IsNullOrWhiteSpace($Command)){return $false}; $i="$Name $Command"; if($i-match$Protected){return $false}; return($Name-match'(?i)(MicrosoftEdgeAutoLaunch|EdgeAutoLaunch|msedge)'-and$Command-match'(?i)(^|[\\\"\s])msedge\.exe([\"\s]|$)'-and$Command-match'(?i)(--no-startup-window|--win-session-start|--auto-launch-at-startup|--restore-last-session)') }
function Get-Candidates { $r=@(); foreach($p in $RunPaths){if(-not(Test-Path $p)){continue};$k=Get-Item -LiteralPath $p;foreach($n in $k.GetValueNames()){$v=[string]$k.GetValue($n,$null,'DoNotExpandEnvironmentNames');if(Test-Candidate $n $v){$r+=[pscustomobject]@{Path=$p;Name=$n;Value=$v;Kind=$k.GetValueKind($n).ToString()}}};};@($r) }
function Save-State([array]$Candidates){$d=Split-Path -Parent $StatePath;if($d-and-not(Test-Path $d)){New-Item -ItemType Directory -Path $d -Force|Out-Null};[ordered]@{schemaVersion=1;experiment='EXP-015';capturedUtc=(Get-Date).ToUniversalTime().ToString('o');candidates=$Candidates}|ConvertTo-Json -Depth 8|Set-Content -LiteralPath $StatePath -Encoding UTF8}
function Read-State{if(-not(Test-Path $StatePath)){throw"State file missing: $StatePath"};$s=Get-Content -LiteralPath $StatePath -Raw|ConvertFrom-Json;if($s.experiment-ne'EXP-015'-or$s.schemaVersion-ne1){throw'State identity validation failed.'};$s}
try{$support=Get-Support;if(-not$support.Supported){Write-Event support unsupported @{support=$support};throw'Supported HP Windows 11 system with Microsoft Edge was not detected.'};$current=Get-Candidates;switch($Action){'Check'{Write-Event inventory ok @{count=$current.Count;support=$support};$current}'DryRun'{Write-Event dry-run ok @{count=$current.Count};$current}'Apply'{if(-not(Test-Path $StatePath)){Save-State $current};$s=Read-State;foreach($c in @($s.candidates)){if(-not(Test-Candidate $c.Name $c.Value)){throw"Candidate identity changed: $($c.Path)::$($c.Name)"};if($PSCmdlet.ShouldProcess("$($c.Path)::$($c.Name)",'Remove Edge auto-launch registration')){Remove-ItemProperty -LiteralPath $c.Path -Name $c.Name -ErrorAction Stop}};if((Get-Candidates).Count-ne0){throw'Application verification failed.'};Write-Event apply ok @{removed=@($s.candidates).Count}}'Verify'{if((Get-Candidates).Count-ne0){throw'One or more bounded Edge auto-launch registrations remain.'};Write-Event verify ok @{remaining=0}}'VerifyReboot'{$s=Read-State;if((Get-Candidates).Count-ne0){throw'Reboot persistence verification failed.'};Write-Event verify-reboot ok @{capturedUtc=$s.capturedUtc}}'Rollback'{$s=Read-State;foreach($c in @($s.candidates)){if($PSCmdlet.ShouldProcess("$($c.Path)::$($c.Name)",'Restore Edge auto-launch registration')){if(-not(Test-Path $c.Path)){New-Item -Path $c.Path -Force|Out-Null};New-ItemProperty -LiteralPath $c.Path -Name $c.Name -Value $c.Value -PropertyType $c.Kind -Force|Out-Null};$a=Get-ItemPropertyValue -LiteralPath $c.Path -Name $c.Name -ErrorAction Stop;if([string]$a-ne[string]$c.Value){throw"Rollback verification failed: $($c.Path)::$($c.Name)"}};Write-Event rollback ok @{restored=@($s.candidates).Count}}}}catch{Write-Event failure error @{message=$_.Exception.Message};throw}
